/**
 * Shipping group details
 */
export const zCreateOrderShippingGroupBody = z
  .object({
    data: z
      .object({
        type: z.literal("shipping_group"),
        shipping_type: z
          .string()
          .register(z.globalRegistry, {
            description: "The shipping type for this group",
          })
          .optional(),
        tracking_reference: z
          .string()
          .register(z.globalRegistry, {
            description: "Tracking reference for the shipment",
          })
          .optional(),
        address: z
          .object({
            first_name: z.string().optional(),
            last_name: z.string().optional(),
            phone_number: z.string().optional(),
            company_name: z.string().optional(),
            line_1: z.string().optional(),
            line_2: z.string().optional(),
            city: z.string().optional(),
            postcode: z.string().optional(),
            county: z.string().optional(),
            country: z.string().optional(),
            region: z.string().optional(),
            instructions: z.string().optional(),
          })
          .optional(),
        delivery_estimate: z
          .object({
            start: z.iso.datetime().optional(),
            end: z.iso.datetime().optional(),
          })
          .optional(),
      })
      .optional(),
  })
  .register(z.globalRegistry, {
    description: "Shipping group details",
  })

